import { PaperclipAgent } from '@paperclip/sdk';

const agent = new PaperclipAgent({ name: 'CodeReviewer' });
agent.start();

import { applyTasteSkill } from 'taste-skill';

await applyTasteSkill({
  agent: 'claude-code',
  direction: 'modern-dark',
  verifyInBrowser: true
});

import { configureEcc } from 'ecc-agents';

configureEcc({
  harness: 'claude-code',
  memorySync: true,
  securityGuardrails: ['strict']
});

import { renderVideo } from 'hyperframes';

await renderVideo({
  template: '<div><h1>Hello AI Video</h1></div>',
  output: 'output.mp4'
});

import { analyzeBinary } from 'rea-agents';

const report = await analyzeBinary({
  target: './app.bin',
  depth: 'deep',
  mcpEnabled: true
});
console.log(report.summary);

import { test } from 'e2e';

test('user login flow', async ({ page }) => {
  await page.goto('/login');
  await page.fill('#username', 'developer');
  await page.click('button[type="submit"]');
  await page.expect(page.locator('.dashboard')).toBeVisible();
});

